<?php
declare(strict_types=1);
require __DIR__.'/common.php';$u=cloud_user();$d=db();try{$p=video_playlist($d,video_id($_GET['id']??null),(int)$u['id']);}catch(InvalidArgumentException){$p=null;}
if(!$p){$d->close();http_response_code(404);head('Nie znaleziono playlisty');echo '<a class="btn btn-primary" href="video_playlists.php">Moje playlisty</a>';foot();exit;}
$owner=(int)$p['idu']===(int)$u['id'];
$s=$d->prepare('SELECT s.*,m.name AS genre,u.username,x.idpldb FROM z6v_playlistdatabase x JOIN z6v_film s ON s.idf=x.idf JOIN z6v_filmtype m ON m.idft=s.idft JOIN z6_users u ON u.id=s.idu WHERE x.idpl=? ORDER BY x.idpldb');$s->bind_param('i',$p['idpl']);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$own=video_own_playlists($d,(int)$u['id']);
$available=[];if($owner){$s=$d->prepare('SELECT s.idf,s.title,s.director FROM z6v_film s WHERE '.video_access_sql().' AND NOT EXISTS(SELECT 1 FROM z6v_playlistdatabase x WHERE x.idpl=? AND x.idf=s.idf) ORDER BY s.title,s.idf');$s->bind_param('iii',$u['id'],$u['id'],$p['idpl']);$s->execute();$available=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$d->close();
$queue=array_map(fn($s)=>['id'=>(int)$s['idf'],'title'=>$s['title'],'director'=>$s['director'],'url'=>'film_file.php?id='.(int)$s['idf']],$rows);
head($p['name']);video_toolbar($owner?'video_playlists.php':'video_playlists.php?public=1');
?>
<div class="d-flex flex-wrap gap-3 align-items-center mb-4"><?=video_cover_html(null,(int)$p['idpl'],$p['coverfilename'],'Okładka '.$p['name'],true)?><span class="badge <?=$p['public']?'text-bg-success':'text-bg-secondary'?>"><?=$p['public']?'Publiczna':'Prywatna'?></span><span class="text-body-secondary"><?=h($p['username'])?> · <?=count($rows)?> filmów · <?=h(cloud_time($p['datetime']))?></span></div>
<?php if($rows): ?>
<section class="card mb-4 video-player" data-queue="<?=h(json_encode($queue,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR))?>"><div class="card-body p-4"><p class="h5 mb-1" id="now-title"><?=h($rows[0]['title'])?></p><p class="text-body-secondary" id="now-director"><?=h($rows[0]['director'])?></p><video class="video-media w-100" id="playlist-player" controls preload="none" src="film_file.php?id=<?=$rows[0]['idf']?>"><track id="playlist-subtitles" kind="subtitles" src="film_subtitles.php?id=<?=$rows[0]['idf']?>" srclang="pl" label="Polski"></video><div class="d-flex align-items-center flex-wrap gap-2 mt-3"><button class="btn btn-outline-light" id="previous-film" type="button" disabled>⏮ Poprzedni</button><button class="btn btn-primary" id="play-playlist" type="button">▶ Odtwórz playlistę</button><button class="btn btn-outline-light" id="next-film" type="button"<?=count($rows)<2?' disabled':''?>>Następny ⏭</button><span class="small text-body-secondary ms-2" id="queue-position">1 / <?=count($rows)?></span></div><p class="small text-body-secondary mt-2 mb-0" role="status" id="player-status"></p></div></section>
<div class="list-group mb-4"><?php foreach($rows as $i=>$film): ?><article class="list-group-item video-track" data-row="<?=$i?>"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3"><div class="d-flex align-items-center gap-3"><button type="button" class="btn btn-outline-primary video-track-play" data-track="<?=$i?>" aria-label="Odtwórz <?=h($film['title'])?>"><?=$i+1?> ▶</button><div><a href="film.php?id=<?=$film['idf']?>" class="fw-semibold"><?=h($film['title'])?></a><div class="small text-body-secondary"><?=h($film['director'])?> · <?=h($film['genre'])?></div></div></div><div class="d-flex flex-wrap align-items-center gap-2"><?php if($owner): ?><form method="post" action="video_action.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(video_csrf())?>"><input type="hidden" name="action" value="remove_film"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><input type="hidden" name="film" value="<?=$film['idf']?>"><button class="btn btn-outline-danger btn-sm" type="submit" aria-label="Usuń <?=h($film['title'])?> z playlisty">Usuń z playlisty</button></form><?php else: video_add_form($film,$own,(int)$p['idpl']); endif; ?></div></div></article><?php endforeach; ?></div>
<?php else: ?><div class="card card-body text-center py-4 mb-4"><p class="mb-0">Ta playlista jest pusta.</p></div><?php endif; ?>
<?php if($owner): ?>
<?php if($available): ?><section class="card mb-4"><div class="card-body p-4"><h2 class="h5 mb-3">Dodaj film do playlisty</h2><form method="post" action="video_action.php" class="d-flex flex-wrap gap-2"><input type="hidden" name="csrf" value="<?=h(video_csrf())?>"><input type="hidden" name="action" value="add_film"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><label class="visually-hidden" for="add-existing-film">Film</label><select class="form-select video-track-select" id="add-existing-film" name="film" required><option value="">Wybierz film</option><?php foreach($available as $film): ?><option value="<?=$film['idf']?>"><?=h($film['title'].' — '.$film['director'])?></option><?php endforeach; ?></select><button class="btn btn-primary" type="submit">Dodaj do playlisty</button></form></div></section><?php endif; ?>
<details class="card"><summary class="p-3">Ustawienia playlisty</summary><div class="card-body p-4 pt-0"><form method="post" action="video_action.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(video_csrf())?>"><input type="hidden" name="action" value="update_playlist"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><label class="form-label" for="edit-playlist-name">Nazwa</label><input class="form-control mb-3" name="name" id="edit-playlist-name" value="<?=h($p['name'])?>" maxlength="160" required><div class="form-check mb-3"><input class="form-check-input" type="checkbox" id="playlist-public" name="public" value="1"<?=$p['public']?' checked':''?>><label class="form-check-label" for="playlist-public">Playlista publiczna</label></div><label class="form-label" for="edit-playlist-cover">Nowa okładka (opcjonalnie)</label><input class="form-control mb-3" type="file" id="edit-playlist-cover" name="cover" accept="image/png,image/jpeg,image/webp"><button class="btn btn-primary" type="submit">Zapisz ustawienia</button></form><hr><form method="post" action="video_action.php" class="video-delete" data-confirm="Usunąć playlistę?"><input type="hidden" name="csrf" value="<?=h(video_csrf())?>"><input type="hidden" name="action" value="delete_playlist"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><button class="btn btn-outline-danger" type="submit">Usuń playlistę</button></form></div></details>
<?php endif; ?>
<?php foot(); ?>
